            },
            {
              "rating": 3,
              "description": "```Good at managing multiple tasks and meeting project goals```"
            },
            {
              "rating": 4,
              "description": "```Excellent project management skills; helps team improve processes```"
            }
          ]
        }
      ]
    },
    {
      "category": "Collaboration",
      "criteria": [
