            {
              "rating": 3,
              "description": "```Regularly helps team members and shares knowledge```"
            },
            {
              "rating": 4,
              "description": "```Actively mentors others and contributes to team growth```"
            }
          ]
        }
      ]
    },
    {
      "category": "Innovation & Growth",
      "criteria": [
        {
          "name": "Learning & Development",
          "levels": [
            {
              "rating": 1,
              "description": "```Shows little interest in learning new technologies or skills```"
            },
            {
              "rating": 2,
              "description": "```Learns new skills when required for projects```"
            },
            {
              "rating": 3,
              "description": "```Proactively learns new technologies and best practices```"
            },
            {
              "rating": 4,
              "description": "```Consistently stays ahead of technology trends; brings new ideas to the team```"
