            },
            {
              "rating": 3,
              "description": "```Regularly proposes and implements innovative solutions```"
            },
            {
              "rating": 4,
              "description": "```Drives innovation and technical excellence in the team```"
            }
          ]
        }
      ]
    }
  ],
  "rating_scale": {
